package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.ruoyi.medical.contracts.*;
import com.ruoyi.medical.identity.*;
import com.ruoyi.medical.persistence.mapper.*;
import java.util.*;
import java.util.function.Function;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
/** Real policy and immutable journal. Typed GET proof is an explicit fixture here; separate real-reader tests cover domain rejection. */
class FormalEvaluationPolicyServiceTest {
 final PolicyStorageFixture f=new PolicyStorageFixture();final FormalEvaluationPolicySchema schema=new FormalEvaluationPolicySchema();
 final EnterpriseAccess access=mock(EnterpriseAccess.class);final ApplicationSessionIdentity.Verified subject=mock(ApplicationSessionIdentity.Verified.class);
 final FormalEvaluationPolicyInputs input=mock(FormalEvaluationPolicyInputs.class);final FormalEvaluationPolicyInputs.Prepared prepared=mock(FormalEvaluationPolicyInputs.Prepared.class);
 final FormalEvaluationPolicyMapper storage=mock(FormalEvaluationPolicyMapper.class);final Map<String,FormalEvaluationPolicyMapper.Snapshot> rows=new HashMap<>();
 final EvaluationAcceptancePolicyService service=new EvaluationAcceptancePolicyService(f.json,access,f.journal,f.guarded,storage,f.schema,schema,f.evidence,input,f.resources,new IdentityDirectoryPolicy("INTERNAL"));
 final ObjectNode snapshot=f.json.object().put("schema_version","1.0.0").put("input_schema_sha256","a".repeat(64)).put("classification","INTERNAL");
 FormalEvaluationPolicyServiceTest()throws Exception{
  when(access.execute(eq(subject),any())).thenAnswer(i->f.scoped(()->((Function<EnterpriseAccess.Admission,Object>)i.getArgument(1)).apply(f.a)));
  when(input.prepare(eq(subject),eq("1"),any(),anyBoolean())).thenReturn(prepared);when(prepared.snapshot()).thenAnswer(i->snapshot.deepCopy());when(prepared.authorizations()).thenReturn(f.json.object().put("synthetic_typed_proof",true));when(prepared.dependencyVersions()).thenReturn(List.of(PolicyStorageFixture.id(5)));
  // Consumer preparation now wraps the same human session in EvidenceReadAccess.
  // Preserve the existing executionEligible-specific stubs, including revocation, rather than returning an unconditional proof.
  when(input.prepare(any(EvidenceReadAccess.class),eq("1"),any(),anyBoolean())).thenAnswer(i->{
   EvidenceReadAccess reader=i.getArgument(0);assertFalse(reader.control());
   assertSame(f.a,reader.execute(a->a));
   return input.prepare(subject,i.getArgument(1),i.getArgument(2),i.getArgument(3));
  });
  when(storage.insertSnapshot(anyMap())).thenAnswer(i->{var row=(FormalEvaluationPolicyMapper.Snapshot)((Map<?,?>)i.getArgument(0)).get("snapshot");assertNull(rows.putIfAbsent(row.recordId(),row));return 1;});
  when(storage.snapshot(anyMap())).thenAnswer(i->{var row=rows.get(((Map<?,?>)i.getArgument(0)).get("recordId"));return row==null?List.of():List.of(row);});
 }
 ObjectNode author(){var n=f.json.object().put("schema_version","1.0.0").put("sampling_assessment","Human review of fixed source family assumptions");n.set("specification",f.policy());var u=n.putArray("root_uses").addObject().put("purpose","EVALUATION_RESULTS");u.set("version",f.json.tree(new PermissionProtocol.Basis(PolicyStorageFixture.id(5),PolicyStorageFixture.H)));return n;}
 ObjectNode decision(JsonNode draft,String choice){return f.decision(draft,choice).put("sampling_assessment","Independent human assessment of fixed independence evidence");}
 JsonNode draft()throws Exception{return service.author(subject,"1","formal-policy-test-001",author());}
 JsonNode approve()throws Exception{var d=draft();f.actor=PolicyStorageFixture.id(3);f.now=f.now.plusMinutes(1);return service.decide(subject,"1","formal-policy-decision-001",decision(d,"APPROVE"));}
 @Test void authorCreatesImmutableSnapshotAndAuditedOriginalKeyReplay()throws Exception{var d=draft();assertEquals(1,rows.size());assertEquals(1,f.audits.size());assertEquals(1,f.events.size());assertEquals(d,draft());assertEquals(1,rows.size());verify(prepared,atLeastOnce()).requireConsumer(eq(f.a),eq(author()),eq(true));}
 @Test void changedCanonicalBodyCannotReuseOriginalKey()throws Exception{draft();var request=author().put("sampling_assessment","Different assessment");assertEquals(ErrorCode.IDEMPOTENCY_CONFLICT,assertThrows(TenantAccessException.class,()->service.author(subject,"1","formal-policy-test-001",request)).code());}
 @Test void sameAuthorCannotApprove()throws Exception{var d=draft();assertThrows(TenantAccessException.class,()->service.decide(subject,"1","formal-policy-decision-001",decision(d,"APPROVE")));assertEquals(1,rows.size());}
 @Test void actualIndependentDecisionHasHumanThresholdAndPrivateProof()throws Exception{var d=approve();var p=service.prepare(subject,"1",d.required("resource_id").asText(),d.required("content_sha256").asText());var verified=f.scoped(()->service.require(f.a,d.required("resource_id").asText(),d.required("content_sha256").asText(),p));assertEquals("0.8",verified.policy().dimensions().get(0).threshold());assertEquals(2,rows.size());assertEquals(2,f.audits.size());f.scoped(()->{verified.requireUnchanged();return null;});}
 @Test void rejectedPolicyNeverProducesApprovedProof()throws Exception{var d=draft();f.actor=PolicyStorageFixture.id(3);var rejected=service.decide(subject,"1","formal-policy-reject-001",decision(d,"REJECT"));assertThrows(TenantAccessException.class,()->service.prepare(subject,"1",rejected.required("resource_id").asText(),rejected.required("content_sha256").asText()));}
 @Test void draftCannotProduceApprovedProof()throws Exception{var d=draft();assertThrows(TenantAccessException.class,()->service.prepare(subject,"1",d.required("resource_id").asText(),d.required("content_sha256").asText()));}
 @Test void originalSnapshotTamperingBlocksRead()throws Exception{var d=draft();var id=d.required("resource_id").asText();var r=rows.get(id);rows.put(id,new FormalEvaluationPolicyMapper.Snapshot(r.tenantId(),r.recordId(),r.contentSha256(),"{}",r.snapshotSha256(),r.inputSchemaSha256(),r.policySchemaSha256()));assertThrows(TenantAccessException.class,()->service.read(subject,"1",id));}
 @Test void missingSnapshotBlocksLegacyGenericPolicyRecord()throws Exception{var d=draft();rows.clear();assertThrows(TenantAccessException.class,()->service.read(subject,"1",d.required("resource_id").asText()));}
 @Test void changedDownloadedSnapshotBlocksDecision()throws Exception{var d=draft();f.actor=PolicyStorageFixture.id(3);snapshot.put("changed_object_version","v2");assertThrows(TenantAccessException.class,()->service.decide(subject,"1","formal-policy-decision-001",decision(d,"APPROVE")));assertEquals(1,rows.size());}
 @Test void currentTypedProofRevocationBlocksFinalWrite()throws Exception{doThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED)).when(prepared).requireConsumer(any(),any(),anyBoolean());assertThrows(TenantAccessException.class,this::draft);assertTrue(rows.isEmpty());assertTrue(f.records.isEmpty());}
 @Test void currentGovernanceRevocationBlocksRecovery()throws Exception{var d=draft();f.revoked=true;assertThrows(TenantAccessException.class,()->service.recover(subject,"1",d.required("resource_id").asText(),d.required("operation_id").asText()));}
 @Test void anotherActorCannotRecoverOriginalReceipt()throws Exception{var d=draft();f.actor=PolicyStorageFixture.id(3);assertThrows(TenantAccessException.class,()->service.recover(subject,"1",d.required("resource_id").asText(),d.required("operation_id").asText()));}
 @Test void exactOriginalOperationRecoveryWorks()throws Exception{var d=draft();assertEquals(d,service.recover(subject,"1",d.required("resource_id").asText(),d.required("operation_id").asText()));verify(input).prepare(eq(subject),eq("1"),any(),eq(false));}
 @Test void readUsesHistoricalNotExecutableInputAuthority()throws Exception{var d=approve();var result=service.read(subject,"1",d.required("resource_id").asText());assertFalse(result.required("production_eligible").booleanValue());verify(input).prepare(eq(subject),eq("1"),any(),eq(false));}
 @Test void changedApprovalBodyCannotReplay()throws Exception{var d=draft();f.actor=PolicyStorageFixture.id(3);var request=decision(d,"APPROVE");service.decide(subject,"1","formal-policy-decision-001",request);request.put("reason","Changed reason");assertThrows(TenantAccessException.class,()->service.decide(subject,"1","formal-policy-decision-001",request));}
 @Test void secondDecisionCannotReplaceFirst()throws Exception{var d=draft();f.actor=PolicyStorageFixture.id(3);service.decide(subject,"1","formal-policy-decision-001",decision(d,"APPROVE"));assertThrows(TenantAccessException.class,()->service.decide(subject,"1","formal-policy-decision-002",decision(d,"REJECT")));}
 @Test void staleContextStopsBeforeTypedGet()throws Exception{assertThrows(TenantAccessException.class,()->service.author(subject,"2","formal-policy-test-001",author()));verifyNoInteractions(input);}
 @Test void callerCannotInjectApprovalIntoAuthor()throws Exception{var request=author().put("approved",true);assertThrows(SchemaRejection.class,()->service.author(subject,"1","formal-policy-test-001",request));verifyNoInteractions(input);}
 @Test void inconsistentRepeatCountsRejectedBeforeGet()throws Exception{var request=author();var rules=(com.fasterxml.jackson.databind.node.ArrayNode)request.required("specification").required("dimensions");var second=((ObjectNode)rules.get(0)).deepCopy().put("dimension","EVAL-03").put("repeat_count",3);rules.add(second);((ObjectNode)request.required("specification").required("expert_domains")).put("EVAL-03","OTHER_DOMAIN");assertThrows(SchemaRejection.class,()->service.author(subject,"1","formal-policy-test-001",request));verifyNoInteractions(input);}
 @Test void invariantThresholdCannotBeWeakened()throws Exception{var request=author();((ObjectNode)request.required("specification").required("dimensions").get(0)).put("dimension","EVAL-02");((ObjectNode)request.required("specification")).putObject("expert_domains").put("EVAL-02","REGULATORY_DOCUMENT_REVIEW");assertThrows(SchemaRejection.class,()->service.author(subject,"1","formal-policy-test-001",request));verifyNoInteractions(input);}
 JsonNode approvedForConsumer()throws Exception{return approve();}
 EvaluationProtocol.Definition definition(EvaluationAcceptanceStatisticsProtocol.Policy p,String created){var request=new EvaluationProtocol.Create("1.0.0",p.project_id(),p.dataset(),p.sample_manifest_artifact(),List.of(),p.candidate_refs(),p.rule_revision(),List.of("EVAL-01"),new EvaluationProtocol.Variance(2,"REPEAT_ALL","NONE"),p.dataset(),"PRODUCTION","synthetic negative boundary");return new EvaluationProtocol.Definition("1.0.0",p.tenant_id(),PolicyStorageFixture.id(90),request,List.of(),List.of(),PolicyStorageFixture.id(91),"1",PolicyStorageFixture.id(92),created);}
 @Test void policyApprovedAtOrAfterDefinitionCannotBindToEvaluation()throws Exception{var d=approvedForConsumer();var prep=service.prepare(subject,"1",d.required("resource_id").asText(),d.required("content_sha256").asText());f.scoped(()->{var proof=service.require(f.a,d.required("resource_id").asText(),d.required("content_sha256").asText(),prep);assertThrows(TenantAccessException.class,()->proof.requireConsumer(f.a,definition(proof.policy(),proof.policy().approved_at())));assertThrows(TenantAccessException.class,()->proof.requireConsumer(f.a,definition(proof.policy(),"2026-10-18T09:00:00Z")));return null;});}
 @Test void privatePolicyProofCannotCrossAdmissionObject()throws Exception{var d=approvedForConsumer();var prep=service.prepare(subject,"1",d.required("resource_id").asText(),d.required("content_sha256").asText());f.scoped(()->{var proof=service.require(f.a,d.required("resource_id").asText(),d.required("content_sha256").asText(),prep);assertThrows(TenantAccessException.class,()->proof.requireConsumer(mock(EnterpriseAccess.Admission.class),definition(proof.policy(),"2026-10-18T11:00:00Z")));return null;});}
 @Test void candidateAuthorCannotIndependentlyApproveStatistics()throws Exception{snapshot.putObject("candidates").putObject(PolicyStorageFixture.id(100)).put("created_by",PolicyStorageFixture.id(3));var d=draft();f.actor=PolicyStorageFixture.id(3);assertThrows(TenantAccessException.class,()->service.decide(subject,"1","formal-policy-decision-001",decision(d,"APPROVE")));assertEquals(1,rows.size());}
 @Test void domainIsOriginalApprovedSpecificationAndAbsentFromFrozenStatistics()throws Exception{var d=approve();var p=service.prepare(subject,"1",d.required("resource_id").asText(),d.required("content_sha256").asText());f.scoped(()->{var proof=service.require(f.a,d.required("resource_id").asText(),d.required("content_sha256").asText(),p);assertEquals("REGULATORY_DOCUMENT_REVIEW",proof.expertDomain("EVAL-01"));assertEquals("INTERNAL",proof.classification());assertThrows(TenantAccessException.class,()->proof.expertDomain("EVAL-02"));assertThrows(TenantAccessException.class,()->proof.expertDomain(null));assertFalse(f.json.tree(proof.policy()).has("expert_domains"));return null;});}
 @Test void changedDomainCannotReuseOriginalAuthorKey()throws Exception{draft();var n=author();((ObjectNode)n.required("specification").required("expert_domains")).put("EVAL-01","OTHER_QUALIFICATION");assertEquals(ErrorCode.IDEMPOTENCY_CONFLICT,assertThrows(TenantAccessException.class,()->service.author(subject,"1","formal-policy-test-001",n)).code());}
 @Test void decisionCannotRetroactivelyChooseQualificationDomain()throws Exception{var d=draft();f.actor=PolicyStorageFixture.id(3);var request=decision(d,"APPROVE");request.putObject("expert_domains").put("EVAL-01","RETROSPECTIVE");assertThrows(SchemaRejection.class,()->service.decide(subject,"1","formal-policy-decision-001",request));assertEquals(1,rows.size());}
 @Test void historicalProofKeepsApprovedDomainsWhenExecutionEligibilityStops()throws Exception{var originalDraft=draft();f.actor=PolicyStorageFixture.id(3);f.now=f.now.plusMinutes(1);var d=service.decide(subject,"1","formal-policy-decision-001",decision(originalDraft,"APPROVE"));when(input.prepare(eq(subject),eq("1"),any(),eq(true))).thenThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED));var checked=mock(EvaluationAcceptanceInputSchema.CheckedInputs.class);when(checked.canonicalSampleManifest()).thenReturn("[]");when(prepared.checked()).thenReturn(checked);String id=d.required("resource_id").asText(),hash=d.required("content_sha256").asText();assertThrows(TenantAccessException.class,()->service.prepare(subject,"1",id,hash));var p=service.prepareHistorical(subject,"1",id,hash);f.scoped(()->{var proof=service.requireHistorical(f.a,id,hash,p);assertEquals("REGULATORY_DOCUMENT_REVIEW",proof.expertDomain("EVAL-01"));assertEquals("INTERNAL",proof.classification());proof.requireConsumer(f.a,definition(proof.policy(),"2026-10-18T11:00:00Z"));proof.requireUnchanged();assertFalse(proof.authorizations().isEmpty());assertEquals(List.of(PolicyStorageFixture.id(5),originalDraft.required("resource_id").asText(),id).stream().sorted().toList(),proof.dependencyVersions());assertThrows(TenantAccessException.class,()->service.require(f.a,id,hash,p));return null;});var captured=org.mockito.ArgumentCaptor.forClass(JsonNode.class);verify(prepared,atLeastOnce()).requireConsumer(eq(f.a),captured.capture(),eq(false));assertEquals(f.schema.canonical(author()),f.schema.canonical(captured.getValue()));}
 @Test void activePreparationCannotConstructHistoricalProof()throws Exception{var d=approve();String id=d.required("resource_id").asText(),hash=d.required("content_sha256").asText();var p=service.prepare(subject,"1",id,hash);f.scoped(()->{assertThrows(TenantAccessException.class,()->service.requireHistorical(f.a,id,hash,p));return null;});}
 @Test void historicalProofRejectsUnapprovedOriginals()throws Exception{var d=draft();assertThrows(TenantAccessException.class,()->service.prepareHistorical(subject,"1",d.required("resource_id").asText(),d.required("content_sha256").asText()));f.actor=PolicyStorageFixture.id(3);var rejected=service.decide(subject,"1","formal-policy-reject-001",decision(d,"REJECT"));assertThrows(TenantAccessException.class,()->service.prepareHistorical(subject,"1",rejected.required("resource_id").asText(),rejected.required("content_sha256").asText()));}
 @Test void historicalProofStillRequiresOriginalHashAndCurrentTypedRead()throws Exception{var d=approve();String id=d.required("resource_id").asText(),hash=d.required("content_sha256").asText();assertThrows(TenantAccessException.class,()->service.prepareHistorical(subject,"1",id,"b".repeat(64)));var p=service.prepareHistorical(subject,"1",id,hash);doThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED)).when(prepared).requireConsumer(any(),any(),eq(false));f.scoped(()->{assertThrows(TenantAccessException.class,()->service.requireHistorical(f.a,id,hash,p));return null;});}
 @Test void historicalProofIsBoundToSameAdmissionAndOriginalDefinition()throws Exception{var d=approve();String id=d.required("resource_id").asText(),hash=d.required("content_sha256").asText();var p=service.prepareHistorical(subject,"1",id,hash);f.scoped(()->{var proof=service.requireHistorical(f.a,id,hash,p);assertThrows(TenantAccessException.class,()->proof.requireConsumer(mock(EnterpriseAccess.Admission.class),definition(proof.policy(),"2026-10-18T11:00:00Z")));assertThrows(TenantAccessException.class,()->proof.requireConsumer(f.a,definition(proof.policy(),proof.policy().approved_at())));assertThrows(TenantAccessException.class,()->proof.expertDomain("EVAL-03"));return null;});}
 @Test void historicalProofRevocationAndSnapshotTamperingRemainDenied()throws Exception{var d=approve();String id=d.required("resource_id").asText(),hash=d.required("content_sha256").asText();var p=service.prepareHistorical(subject,"1",id,hash);f.scoped(()->{var proof=service.requireHistorical(f.a,id,hash,p);f.revoked=true;assertThrows(TenantAccessException.class,proof::requireUnchanged);f.revoked=false;var r=rows.get(id);rows.put(id,new FormalEvaluationPolicyMapper.Snapshot(r.tenantId(),r.recordId(),r.contentSha256(),"{}",r.snapshotSha256(),r.inputSchemaSha256(),r.policySchemaSha256()));assertThrows(TenantAccessException.class,proof::requireUnchanged);return null;});}
 @Test void historicalProofTypeHasNoPublicConstructor(){assertEquals(0,EvaluationAcceptancePolicyService.HistoricalPolicy.class.getConstructors().length);assertFalse(EvaluationAcceptancePolicyService.VerifiedPolicy.class.isAssignableFrom(EvaluationAcceptancePolicyService.HistoricalPolicy.class));}
 @Test void sensitiveTypedInputsCannotBeDowngradedByConfiguredDefault()throws Exception{snapshot.put("classification","PERSONAL_HEALTH");var d=approve();for(var row:f.records.values()){assertEquals("PERSONAL_HEALTH",row.classification());assertEquals("PERSONAL_HEALTH",f.schema.read(row.contentJson()).required("classification").asText());}assertNotNull(service.read(subject,"1",d.required("resource_id").asText()));}
 @Test void unsupportedClassificationFailsBeforeJournalWrite()throws Exception{snapshot.put("classification","CONFIDENTIAL");assertThrows(TenantAccessException.class,this::draft);assertTrue(f.records.isEmpty());}
}
